  1994	static int rar5_read_header(struct archive_read *a,
  1995	        struct archive_entry *entry)
  1996	{
  1997	    struct rar5* rar = get_context(a);
  1998	    int ret;
  1999	
  2000	    if(rar->header_initialized == 0) {
  2001	        init_header(a);
  2002	        rar->header_initialized = 1;
  2003	    }
  2004	
  2005	    if(rar->skipped_magic == 0) {
  2006	        if(ARCHIVE_OK != consume(a, rar5_signature_size)) {
  2007	            return ARCHIVE_EOF;
  2008	        }
  2009	
  2010	        rar->skipped_magic = 1;
  2011	    }
  2012	
  2013	    do {
  2014	        ret = process_base_block(a, entry);
  2015	    } while(ret == ARCHIVE_RETRY ||
  2016	            (rar->main.endarc > 0 && ret == ARCHIVE_OK));
  2017	
  2018	    return ret;
  2019	}
