  2045	static void update_crc(struct rar5* rar, const uint8_t* p, size_t to_read) {
  2046	    int verify_crc;
  2047	
  2048	    if(rar->skip_mode) {
  2049	#if defined CHECK_CRC_ON_SOLID_SKIP
  2050	        verify_crc = 1;
  2051	#else
  2052	        verify_crc = 0;
  2053	#endif
  2054	    } else
  2055	        verify_crc = 1;
  2056	
  2057	    if(verify_crc) {
  2058	        /* Don't update CRC32 if the file doesn't have the `stored_crc32` info
  2059	           filled in. */
  2060	        if(rar->file.stored_crc32 > 0) {
  2061	            rar->file.calculated_crc32 =
  2062	                crc32(rar->file.calculated_crc32, p, to_read);
  2063	        }
  2064	
  2065	        /* Check if the file uses an optional BLAKE2sp checksum algorithm. */
  2066	        if(rar->file.has_blake2 > 0) {
